var chart;
var radius;
var zoom = 0.5;
var tzoom = 1;
var rx = 0;
var tx = 0;
var pos, tpos;
var animate = true;
var markers = [50, 20, 10, 5.0, 4.0, 3.0, 2.0, 1.8, 1.6, 1.4, 1.2, 1.0, 0.9, 0.8, 0.7, 0.6, 0.5, 0.4, 0.3, 0.2, 0.15, 0.1, 0.05, 0];
var vals = [50, 35, 20, 18, 16, 14, 12, 10, 9, 8, 7, 6, 5.0, 4.8, 4.6, 4.4, 4.2, 4.0, 3.8, 3.6, 3.4, 3.2, 3.0, 2.8, 2.6, 2.4, 2.2, 2.0, 1.95, 1.9, 1.85, 1.8, 1.75, 1.7, 1.65, 1.6, 1.55, 1.5, 1.45, 1.4, 1.35, 1.3, 1.25, 1.2, 1.15, 1.1, 1.05, 1.0, 0.95, 0.9, 0.85, 0.8, 0.75, 0.7, 0.65, 0.6, 0.55, 0.5, 0.48, 0.46, 0.44, 0.42, 0.4, 0.38, 0.36, 0.34, 0.32, 0.3, 0.28, 0.26, 0.24, 0.22, 0.2, 0.19, 0.18, 0.17, 0.16, 0.15, 0.14, 0.13, 0.12, 0.11, 0.1, 0.09, 0.08, 0.07, 0.06, 0.05, 0.04, 0.03, 0.02, 0.01, 0]
var phrase1 = '→ WAVELENGTHS TOWARD GENERATOR →';
var phrase2 = '← WAVELENGTHS TOWARD LOAD ←';
var phrase3 = 'CAPACITVE REACTANCE COMPONENT OR INDUCTIVE SUSCEPTANCE';
var phrase4 = 'INDUCTIVE REACTANCE COMPONENT OR CAPACITIVE SUSCEPTANCE';
var phrase5 = 'ANGLE OF REFLECTION COEFFICIENT IN DEGREES';
